export function t(id, ...values) {
  return fill(messages[id]?.[0] ?? id, values);
}

export const fill = (template, values) => (values.length ? template.replace(/\{(\d+)\}/g, (hole, index) => (index < values.length ? String(values[index]) : hole)) : template);
